// The mannequin of the sketch editor's pose tool. Every shape here is generated by this file (no downloaded model).
// The body is built in segments with joint balls between them, and front and back differ in shape:
// a faceted face against a smooth skull, a broad back, kneecaps, calves, heels and toes.
// The forms stay restrained, like an artist's mannequin: the pelvis is one smooth piece; the female chest rises only
// slightly and the male body has no bulge anywhere. Nothing is exaggerated.
// Figure frame: +X is the person's own left, +Y up, +Z the way the person faces; metres; origin on the floor.
import * as THREE from './vendor/three/three.module.min.js';

const DEG = Math.PI / 180;

export const DIM = {
    rootY: 0.94, thigh: 0.45, shin: 0.43, spine: 0.10, chest: 0.18, neck: 0.22, head: 0.10,
    shoulderY: 0.18, upper: 0.29, fore: 0.26,
};

const GENDER = {
    male: { scale: 1.0, sh: 0.2, hip: 0.092, chestW: 0.176, chestD: 1.0, waistW: 0.132, pelvisW: 0.152, limb: 1.0, e: 2.5, head: 1.0, neck: 0.045 },
    female: { scale: 0.93, sh: 0.17, hip: 0.098, chestW: 0.146, chestD: 0.9, waistW: 0.108, pelvisW: 0.16, limb: 0.87, e: 2.15, head: 0.97, neck: 0.037 },
};
const BUILD = {
    standard: { w: 1.0, m: 1.0, sh: 0 },
    slim: { w: 0.88, m: 0.84, sh: -0.01 },
    strong: { w: 1.1, m: 1.2, sh: 0.014 },
};
// Finger curl 0..1 for index, middle, ring, little, then the thumb; spread in degrees. label: [English, Chinese].
export const HAND_SHAPES = {
    relax: { label: ['Relaxed', '放松'], curl: [0.22, 0.3, 0.36, 0.42], thumb: 0.25, spread: 3 },
    open: { label: ['Open', '张开'], curl: [0, 0, 0, 0], thumb: 0, spread: 9 },
    fist: { label: ['Fist', '握拳'], curl: [1, 1, 1, 1], thumb: 1, spread: 0 },
    point: { label: ['Point', '指向'], curl: [0, 1, 1, 1], thumb: 0.9, spread: 0 },
    cup: { label: ['Cupped', '托握'], curl: [0.5, 0.55, 0.6, 0.65], thumb: 0.05, spread: 2 },
};

// A closed tube through elliptical rings. Each ring is [y, halfWidthX, depthFront, depthBack, centreX, centreZ];
// front and back depths differ, which is how one segment gets a chest and a back, or a shin and a calf.
// `e` is the superellipse exponent (2 = ellipse, larger = boxier). `sub(x, y, z)` may label faces with a region number.
export function loft(rings, o = {}) {
    const seg = o.seg ?? 28, e = o.e ?? 2, capK = o.cap ?? 0.7;
    const R = rings.map(r => ({ y: r[0], rx: r[1], zf: r[2] ?? r[1], zb: r[3] ?? r[2] ?? r[1], cx: r[4] || 0, cz: r[5] || 0 }))
        .sort((a, b) => a.y - b.y);
    if (o.steps) {     // a smooth curve through the rings (Catmull-Rom), so the profile has no corners
        const src = R.slice(), cr = (a, b, c, d, t) => 0.5 * (2 * b + (c - a) * t + (2 * a - 5 * b + 4 * c - d) * t * t + (3 * b - a - 3 * c + d) * t * t * t);
        R.length = 0;
        for (let i = 0; i < src.length - 1; i++) {
            const p = [src[Math.max(0, i - 1)], src[i], src[i + 1], src[Math.min(src.length - 1, i + 2)]];
            for (let k = 0; k < o.steps; k++) {
                const t = k / o.steps, r = {};
                for (const key of ['y', 'rx', 'zf', 'zb', 'cx', 'cz']) r[key] = cr(p[0][key], p[1][key], p[2][key], p[3][key], t);
                R.push(r);
            }
        }
        R.push(src[src.length - 1]);
    }
    const cap = (r, dir) => [30, 58, 82].map(t => {
        const c = Math.cos(t * DEG), s = Math.sin(t * DEG), h = capK * Math.min(r.rx, (r.zf + r.zb) / 2);
        return { y: r.y + dir * h * s, rx: r.rx * c, zf: r.zf * c, zb: r.zb * c, cx: r.cx, cz: r.cz, h };
    });
    const all = [...cap(R[0], -1).reverse(), ...R, ...cap(R[R.length - 1], 1)];
    const pos = [], idx = [];
    const pw = v => Math.sign(v) * Math.pow(Math.abs(v), 2 / e);
    for (const r of all) {
        for (let j = 0; j < seg; j++) {
            const a = 2 * Math.PI * j / seg, c = Math.cos(a), s = Math.sin(a);
            const x = r.cx + r.rx * pw(c), z = r.cz + (s >= 0 ? r.zf : r.zb) * pw(s);
            // `swell(x, y, z)` moves the surface along z by a smooth amount: one skin, no added pieces
            pos.push(x, r.y, z + (o.swell ? o.swell(x, r.y, z) * Math.abs(s) * (r.rx / (r.rx + 1e-4)) : 0));
        }
    }
    const n = all.length;
    for (let i = 0; i < n - 1; i++) {
        for (let j = 0; j < seg; j++) {
            const a = i * seg + j, b = i * seg + (j + 1) % seg, c = (i + 1) * seg + j, d = (i + 1) * seg + (j + 1) % seg;
            idx.push(a, c, b, b, c, d);
        }
    }
    const first = all[0], last = all[n - 1];
    const bottom = pos.length / 3; pos.push(first.cx, first.y - 0.02 * first.h, first.cz);
    const top = bottom + 1; pos.push(last.cx, last.y + 0.02 * last.h, last.cz);
    for (let j = 0; j < seg; j++) {
        idx.push(bottom, j, (j + 1) % seg);
        idx.push(top, (n - 1) * seg + (j + 1) % seg, (n - 1) * seg + j);
    }
    let g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    g.setIndex(idx);
    g.computeVertexNormals();
    if (o.sub) g = labelFaces(g, o.sub);
    return g;
}

function labelFaces(g, fn) {
    g = g.toNonIndexed();
    const p = g.attributes.position, sub = new Float32Array(p.count);
    for (let i = 0; i < p.count; i += 3) {
        const v = fn((p.getX(i) + p.getX(i + 1) + p.getX(i + 2)) / 3, (p.getY(i) + p.getY(i + 1) + p.getY(i + 2)) / 3, (p.getZ(i) + p.getZ(i + 1) + p.getZ(i + 2)) / 3);
        sub[i] = sub[i + 1] = sub[i + 2] = v;
    }
    g.setAttribute('sub', new THREE.BufferAttribute(sub, 1));
    return g;
}

// The face: a few flat planes (forehead, two eye-and-cheek planes, the lower face) set proud of the skull.
// The two eye-and-cheek planes are outlined in line art: brow above, bridge of the nose between, cheek line below.
function faceGeometry(sx) {
    const V = {
        TL: [0.044, 0.196, 0.08], TR: [-0.044, 0.196, 0.08],
        BL: [0.064, 0.142, 0.074], BR: [-0.064, 0.142, 0.074], B: [0, 0.136, 0.109],
        CL: [0.064, 0.078, 0.06], CR: [-0.064, 0.078, 0.06], N: [0, 0.084, 0.124],
        JL: [0.04, 0.026, 0.058], JR: [-0.04, 0.026, 0.058], C: [0, 0.008, 0.09],
        IN: [0, 0.1, 0.0],
    };
    const tris = [];
    const poly = (sub, ...names) => { for (let i = 1; i < names.length - 1; i++) tris.push([sub, names[0], names[i], names[i + 1]]); };
    poly(0, 'B', 'TL', 'TR'); poly(0, 'B', 'TR', 'BR'); poly(0, 'B', 'BL', 'TL');
    poly(2, 'B', 'BL', 'CL', 'N'); poly(3, 'B', 'N', 'CR', 'BR');
    poly(0, 'N', 'CL', 'JL', 'C'); poly(0, 'N', 'C', 'JR', 'CR');
    const loop = ['TL', 'BL', 'CL', 'JL', 'C', 'JR', 'CR', 'BR', 'TR'];
    loop.forEach((a, i) => tris.push([0, a, loop[(i + 1) % loop.length], 'IN']));
    const pos = [], sub = [];
    const centre = new THREE.Vector3(0, 0.1, 0.03), a = new THREE.Vector3(), b = new THREE.Vector3(), c = new THREE.Vector3(), nrm = new THREE.Vector3();
    for (const [s, na, nb, nc] of tris) {
        a.set(...V[na]); b.set(...V[nb]); c.set(...V[nc]);
        nrm.crossVectors(b.clone().sub(a), c.clone().sub(a));
        const mid = a.clone().add(b).add(c).multiplyScalar(1 / 3).sub(centre);
        const order = nrm.dot(mid) >= 0 ? [a, b, c] : [a, c, b];
        for (const v of order) { pos.push(v.x * sx, v.y, v.z); sub.push(s); }
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    g.setAttribute('sub', new THREE.Float32BufferAttribute(sub, 1));
    g.computeVertexNormals();
    return g;
}

const SPHERE = new THREE.SphereGeometry(1, 36, 24);

// Builds one figure. Returns { group, J, meshes, mats, fingers, chair }.
export function buildFigure({ gender = 'male', build = 'standard', color = 0xa9bfe0 } = {}) {
    const G = GENDER[gender], B = BUILD[build];
    const W = B.w, M = G.limb * B.m, e = G.e;
    const group = new THREE.Group();
    const J = {}, meshes = [];
    const mats = {
        body: new THREE.MeshStandardMaterial({ color, roughness: 0.6, metalness: 0.02 }),
        face: new THREE.MeshStandardMaterial({ color, roughness: 0.6, metalness: 0.02, flatShading: true }),
        joint: new THREE.MeshStandardMaterial({ color: 0x23262e, roughness: 0.48, metalness: 0.1 }),
        prop: new THREE.MeshStandardMaterial({ color: 0x6f7480, roughness: 0.8 }),
    };
    let pidNext = 1;

    const joint = (name, parent, x, y, z) => {
        const g = new THREE.Group();
        g.name = name; g.position.set(x, y, z); parent.add(g); J[name] = g;
        return g;
    };
    // kind: body | face | joint | prop. o.pid shares the outline group of an earlier mesh; o.sub is its region number.
    const add = (parent, geom, kind, o = {}) => {
        const m = new THREE.Mesh(geom, mats[kind]);
        if (o.pos) m.position.set(...o.pos);
        if (o.scale) m.scale.set(...o.scale);
        if (o.rot) m.rotation.set(o.rot[0] * DEG, o.rot[1] * DEG, o.rot[2] * DEG);
        m.castShadow = true;
        m.userData = { kind, pid: o.pid ?? pidNext++, sub: o.sub ?? 0 };
        parent.add(m); meshes.push(m);
        return m;
    };
    const ball = (parent, pos, radii, kind = 'joint', o = {}) =>
        add(parent, SPHERE.clone(), kind, { ...o, pos, scale: Array.isArray(radii) ? radii : [radii, radii, radii] });

    // Smooth, wide falloff used to shape the torso skin itself.
    const gauss = (d, r) => Math.exp(-(d * d) / (r * r));
    const female = gender === 'female';

    // ---- pelvis
    const root = joint('root', group, 0, DIM.rootY, 0);
    const pw = G.pelvisW * W;
    const pelvis = add(root, loft([
        [0.06, pw * 0.84, 0.084 * W, 0.078 * W], [0.0, pw, 0.094 * W, 0.09 * W],
        [-0.06, pw * 0.95, 0.088 * W, 0.092 * W], [-0.112, pw * 0.5, 0.066 * W, 0.072 * W],
    ], { e, cap: 0.5, seg: 56, steps: 8,
        // female: the back of the hips fills out a little from the waist down and eases back into the thighs; male: flat
        swell: (x, y, z) => (female && z < 0 ? -0.004 * W * gauss(y + 0.045, 0.085) * gauss(Math.abs(x) - 0.06 * W, 0.085) : 0) }), 'body');

    // ---- waist joint and chest
    const spine = joint('spine', root, 0, DIM.spine, 0);
    ball(spine, [0, 0.04, 0], [G.waistW * W * 0.93, 0.1, 0.084 * W]);
    const chest = joint('chest', spine, 0, DIM.chest, 0);
    const cw = G.chestW * W * (build === 'strong' ? 1.04 : 1), cd = G.chestD * W;
    const ribs = add(chest, loft([
        [-0.075, G.waistW * W * 1.04, 0.086 * cd, 0.078 * cd], [0.0, cw * 0.93, 0.104 * cd, 0.094 * cd],
        [0.1, cw * 1.04, 0.108 * cd, 0.1 * cd], [0.17, cw * 0.98, 0.088 * cd, 0.094 * cd],
        [0.212, cw * 0.6, 0.062 * cd, 0.07 * cd], [0.236, cw * 0.36, 0.05 * cd, 0.056 * cd],
    ], { e, cap: 0.3, seg: 64, steps: 8,
        // female: the chest rises a little below the collarbone and eases back into the abdomen; male: flat
        swell: (x, y, z) => (female && z > 0 ? 0.012 * W * gauss(y - 0.075, 0.08) * gauss(Math.abs(x) - 0.05 * W, 0.08) : 0) }), 'body');

    // ---- neck and head
    const neck = joint('neck', chest, 0, DIM.neck, 0);
    add(neck, loft([[0.0, G.neck * 1.06], [0.05, G.neck], [0.1, G.neck * 0.96]], { cap: 0.3, seg: 20 }), 'joint');
    const head = joint('head', neck, 0, DIM.head, 0);
    const hs = G.head;
    const skull = add(head, loft([
        [0.008, 0.04, 0.054, 0.028, 0, 0.014], [0.06, 0.066, 0.08, 0.06], [0.11, 0.078, 0.09, 0.088],
        [0.16, 0.082, 0.092, 0.098], [0.2, 0.074, 0.082, 0.09], [0.23, 0.048, 0.054, 0.058],
    ], { cap: 0.55, seg: 32 }), 'body', { scale: [hs, hs, hs] });
    const hp = skull.userData.pid;
    add(head, faceGeometry(gender === 'female' ? 0.93 : 1), 'face', { pid: hp, scale: [hs, hs, hs] });
    for (const s of [1, -1]) ball(head, [s * 0.08 * hs, 0.108 * hs, -0.004], [0.012, 0.026, 0.017], 'body', { pid: hp, sub: s > 0 ? 5 : 6 });

    const fingers = { L: [], R: [] };
    for (const [side, s] of [['L', 1], ['R', -1]]) {
        // ---- arm
        const sh = joint('shoulder' + side, chest, s * (G.sh + B.sh), DIM.shoulderY, -0.01);
        ball(sh, [0, 0, 0], 0.05 * M);
        add(sh, loft([[-0.03, 0.047 * M, 0.049 * M], [-0.095, 0.052 * M, 0.056 * M, 0.05 * M], [-0.2, 0.042 * M], [-0.262, 0.037 * M]], { seg: 22 }), 'body');
        const el = joint('elbow' + side, sh, 0, -DIM.upper, 0);
        ball(el, [0, 0, 0], 0.036 * M);
        add(el, loft([[-0.03, 0.039 * M], [-0.085, 0.043 * M, 0.042 * M, 0.045 * M], [-0.19, 0.031 * M], [-0.234, 0.027 * M]], { seg: 22 }), 'body');
        const wr = joint('wrist' + side, el, 0, -DIM.fore, 0);
        ball(wr, [0, 0, 0], 0.0255 * M);
        // ---- hand: palm faces the body; fingers hang along -Y and curl towards the palm
        const k = 0.9 + 0.1 * M;
        const palm = add(wr, loft([[-0.02, 0.012, 0.027, 0.026], [-0.058, 0.0145, 0.045, 0.04], [-0.096, 0.0125, 0.045, 0.04]], { e: 3, seg: 18, cap: 0.5 }), 'body', { scale: [k, k, k] });
        const hpid = palm.userData.pid;
        const FZ = [0.034, 0.012, -0.01, -0.031], FL = [0.07, 0.078, 0.072, 0.056], FR = [0.0098, 0.0102, 0.0096, 0.0086];
        const list = [];
        for (let i = 0; i < 4; i++) {
            const f1 = new THREE.Group(); f1.position.set(0, -0.097 * k, FZ[i] * k); wr.add(f1);
            const l1 = FL[i] * 0.54 * k, l2 = FL[i] * 0.46 * k, r = FR[i] * k;
            add(f1, new THREE.CapsuleGeometry(r, l1, 4, 10).translate(0, -l1 / 2, 0), 'body', { pid: hpid, sub: 1 + i });
            const f2 = new THREE.Group(); f2.position.set(0, -l1, 0); f1.add(f2);
            add(f2, new THREE.CapsuleGeometry(r * 0.94, l2 - r, 4, 10).translate(0, -(l2 - r) / 2, 0), 'body', { pid: hpid, sub: 1 + i });
            list.push([f1, f2, FZ[i]]);
        }
        const t1 = new THREE.Group(); t1.position.set(-s * 0.004, -0.034 * k, 0.034 * k); wr.add(t1);
        add(t1, new THREE.CapsuleGeometry(0.0112 * k, 0.036 * k, 4, 10).translate(0, -0.018 * k, 0), 'body', { pid: hpid, sub: 5 });
        const t2 = new THREE.Group(); t2.position.set(0, -0.038 * k, 0); t1.add(t2);
        add(t2, new THREE.CapsuleGeometry(0.0102 * k, 0.024 * k, 4, 10).translate(0, -0.012 * k, 0), 'body', { pid: hpid, sub: 5 });
        fingers[side] = { list, thumb: [t1, t2], s };

        // ---- leg
        const hip = joint('hip' + side, root, s * G.hip * W, 0, 0);
        ball(hip, [0, -0.012, 0], 0.076 * M);
        add(hip, loft([[-0.045, 0.076 * M, 0.08 * M, 0.078 * M], [-0.15, 0.072 * M, 0.08 * M, 0.072 * M], [-0.32, 0.055 * M, 0.057 * M, 0.053 * M], [-0.412, 0.047 * M, 0.048 * M, 0.045 * M]], { seg: 24 }), 'body');
        const kn = joint('knee' + side, hip, 0, -DIM.thigh, 0);
        ball(kn, [0, 0, 0], 0.048 * M);
        ball(hip, [0, -DIM.thigh + 0.012, 0.034 * M], [0.031 * M, 0.04 * M, 0.024 * M], 'body');     // kneecap
        add(kn, loft([[-0.036, 0.046 * M, 0.044 * M, 0.048 * M], [-0.125, 0.049 * M, 0.043 * M, 0.066 * M], [-0.3, 0.035 * M, 0.035 * M, 0.04 * M], [-0.394, 0.03 * M, 0.03 * M, 0.032 * M]], { seg: 24 }), 'body');
        const an = joint('ankle' + side, kn, 0, -DIM.shin, 0);
        ball(an, [0, 0, 0], 0.033 * M);
        // foot: built along its length, then laid forward. Round heel behind, long flat toes in front.
        const fk = 0.92 + 0.08 * M;
        const foot = loft([
            [-0.058, 0.03, 0.028, 0.032, 0, 0.047], [0.0, 0.04, 0.028, 0.05, 0, 0.047], [0.075, 0.046, 0.028, 0.036, 0, 0.047],
            [0.135, 0.049, 0.027, 0.02, 0, 0.048], [0.172, 0.042, 0.024, 0.013, 0, 0.051],
        ], { e: 2.6, seg: 22, cap: 0.6, sub: (x, y) => (y > 0.118 ? 1 : 0) });
        foot.rotateX(Math.PI / 2);
        add(an, foot, 'body', { scale: [fk, 1, fk] });
    }

    // ---- chair (shown when the pose sits)
    const chair = new THREE.Group();
    const box = (w, h, d, x, y, z) => add(chair, new THREE.BoxGeometry(w, h, d), 'prop', { pos: [x, y, z] });
    box(0.46, 0.04, 0.44, 0, 0.44, -0.04);
    for (const x of [-0.2, 0.2]) for (const z of [-0.23, 0.15]) box(0.035, 0.44, 0.035, x, 0.22, z);
    box(0.46, 0.42, 0.03, 0, 0.67, -0.26);
    chair.visible = false;
    group.add(chair);

    for (const m of meshes) {
        m.receiveShadow = false;
        let p = m.parent;
        while (p && !J[p.name]) p = p.parent;
        m.userData.joint = p ? p.name : null;
    }
    group.scale.setScalar(G.scale);
    return { group, J, meshes, mats, fingers, chair, baseScale: G.scale, pidCount: pidNext };
}

// Bakes the outline ids into each mesh: (figure number, part number, region number), all / 255.
// With `grouped`, the part number is the limb the mesh belongs to (torso 1, head 2, arms 3-4, legs 5-6), so the
// drawing has no rings at the joints and reads as one clothed-or-not body rather than a jointed doll.
const GROUP = j => (!j ? 0 : j === 'head' ? 2 : /L$/.test(j) ? (/^(shoulder|elbow|wrist)/.test(j) ? 3 : 5) : /R$/.test(j) ? (/^(shoulder|elbow|wrist)/.test(j) ? 4 : 6) : 1);
export function bakeIds(fig, figureNumber, grouped = false) {
    for (const m of fig.meshes) {
        const part = grouped && m.userData.joint ? GROUP(m.userData.joint) : 10 + m.userData.pid;
        const g = m.geometry, n = g.attributes.position.count, sub = g.attributes.sub;
        const a = new Float32Array(n * 3);
        for (let i = 0; i < n; i++) {
            a[i * 3] = figureNumber / 255; a[i * 3 + 1] = part / 255;
            a[i * 3 + 2] = (sub ? sub.getX(i) : m.userData.sub) / 255;
        }
        g.setAttribute('aId', new THREE.BufferAttribute(a, 3));
    }
}

export function setHandShape(fig, side, name) {
    const shape = HAND_SHAPES[name] || HAND_SHAPES.relax;
    const { list, thumb, s } = fig.fingers[side];
    list.forEach(([f1, f2, z], i) => {
        const c = shape.curl[i];
        f1.rotation.set(-(1.5 - i) * shape.spread * DEG, 0, -s * c * 82 * DEG);
        f2.rotation.set(0, 0, -s * c * 98 * DEG);
    });
    const t = shape.thumb;
    thumb[0].rotation.set((-42 + t * 30) * DEG, 0, -s * (8 + t * 46) * DEG);
    thumb[1].rotation.set(0, 0, -s * t * 62 * DEG);
}
